import { IngestPipeline } from "@514labs/moose-lib";

// User Activity Data Model
// Optimized for:
// 1. Activity counts per user over a date range
// 2. Total duration per action type
export interface UserActivity {
  eventId: string;
  eventTs: Date;
  userId: string;
  action: string;
  durationMs: number; // Nullable duration values will default to 0
}

// Configure the ingestion pipeline with optimized table ordering
// Primary ordering: userId (for user-based queries), eventTs (for date ranges)
// Secondary: action (for action-based aggregations)
export const UserActivityPipeline = new IngestPipeline<UserActivity>("UserActivity", {
  table: {
    orderByFields: ["userId", "eventTs", "action"]
  },
  stream: true,
  ingestApi: true,
});

