const fs = require('fs');
const path = require('path');

// Read and parse the CSV data
const csvPath = '/data/samples/user_activity_sample.csv';
const csvContent = fs.readFileSync(csvPath, 'utf-8');
const lines = csvContent.trim().split('\n');
const headers = lines[0].split(',');

console.log('Headers:', headers);
console.log('Processing', lines.length - 1, 'data rows...');

// Transform each row to match our UserActivity interface
const transformedData = [];
for (let i = 1; i < lines.length; i++) {
  const values = lines[i].split(',');
  if (values.length === headers.length) {
    const record = {
      eventId: values[0].trim(),
      eventTs: values[1].trim(), // ISO string will be parsed by Moose
      userId: values[2].trim(),
      action: values[3].trim(),
      durationMs: parseFloat(values[4].trim()) || 0 // Default nullable values to 0
    };
    transformedData.push(record);
  }
}

console.log('Transformed records:', transformedData.length);
console.log('Sample record:', JSON.stringify(transformedData[0], null, 2));

// Send data to Moose ingestion API
async function loadData() {
  const fetch = (await import('node-fetch')).default;

  for (let i = 0; i < transformedData.length; i++) {
    const record = transformedData[i];

    try {
      const response = await fetch('http://localhost:4000/ingest/UserActivity', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(record)
      });

      if (response.ok) {
        console.log(`✓ Loaded record ${i + 1}/${transformedData.length}: ${record.eventId}`);
      } else {
        const errorText = await response.text();
        console.error(`✗ Failed to load record ${record.eventId}:`, response.status, errorText);
      }
    } catch (error) {
      console.error(`✗ Error loading record ${record.eventId}:`, error.message);
    }
  }

  console.log('Data loading complete!');
}

loadData().catch(console.error);

