// Send data to Moose ingestion API using curl (more reliable than fetch)
async function loadData() {
  const { exec } = require('child_process');
  const util = require('util');
  const execAsync = util.promisify(exec);

  for (let i = 0; i < transformedData.length; i++) {
    const record = transformedData[i];

    try {
      const curlCommand = `curl -X POST -H "Content-Type: application/json" -d '${JSON.stringify(record)}' http://localhost:4000/ingest/UserActivity`;

      const { stdout, stderr } = await execAsync(curlCommand);

      if (stdout.trim() === 'SUCCESS') {
        console.log(`✓ Loaded record ${i + 1}/${transformedData.length}: ${record.eventId}`);
      } else {
        console.error(`✗ Failed to load record ${record.eventId}:`, stdout, stderr);
      }
    } catch (error) {
      console.error(`✗ Error loading record ${record.eventId}:`, error.message);
    }
  }

  console.log('Data loading complete!');
}

